<?php

namespace SilverProtoQoL\RepoFacadeBuilder\Tests;

use Illuminate\Filesystem\Filesystem;
use Orchestra\Testbench\TestCase as Orchestra;
use SilverProtoQoL\RepoFacadeBuilder\RepoFacadeBuilderServiceProvider;

abstract class TestCase extends Orchestra
{
    /**
     * Paths (relative to base_path) generated by tests and wiped between them.
     *
     * @var array<int, string>
     */
    protected array $generated = [
        'app/Repositories',
        'app/Services',
        'app/Facades',
        'app/Enums',
        'app/Interfaces',
        'app/Traits',
        'app/Providers/RepositoryServiceProvider.php',
        'Modules',
        'stubs/repo-facade-builder',
    ];

    protected ?string $providersBackup = null;

    protected function setUp(): void
    {
        parent::setUp();

        $this->clean();

        $bootstrap = base_path('bootstrap/providers.php');
        $this->providersBackup = is_file($bootstrap) ? file_get_contents($bootstrap) : null;
    }

    protected function tearDown(): void
    {
        $this->clean();

        if ($this->providersBackup !== null) {
            file_put_contents(base_path('bootstrap/providers.php'), $this->providersBackup);
        }

        parent::tearDown();
    }

    protected function getPackageProviders($app): array
    {
        return [RepoFacadeBuilderServiceProvider::class];
    }

    protected function clean(): void
    {
        $files = new Filesystem();

        foreach ($this->generated as $path) {
            $path = base_path($path);
            $files->isDirectory($path) ? $files->deleteDirectory($path) : $files->delete($path);
        }
    }

    protected function assertFileContains(string $path, string ...$needles): void
    {
        $this->assertFileExists($path);
        $contents = file_get_contents($path);

        foreach ($needles as $needle) {
            $this->assertStringContainsString($needle, $contents, "Failed asserting [{$path}] contains [{$needle}].");
        }
    }

    protected function assertValidPhp(string $path): void
    {
        exec('php -l '.escapeshellarg($path).' 2>&1', $output, $code);

        $this->assertSame(0, $code, implode("\n", $output));
    }

    /**
     * Create an empty module folder (simulating an existing module).
     */
    protected function makeModuleFolder(string $module, bool $appFolder = false): void
    {
        (new Filesystem())->ensureDirectoryExists(base_path("Modules/{$module}".($appFolder ? '/app' : '')));
    }
}
